set
  title = 'Performance Management',
  goal = 'Performance Management',
  summary = 'A rigorous undergraduate HR course on designing, administering, and improving performance systems. Students learn how goals, competencies, feedback, coaching, appraisal, documentation, calibration, analytics, and legal safeguards work together to improve performance and employee development. This course provides a comprehensive foundation in designing, administering, and improving performance systems, with an emphasis on modern practices including coaching, continuous feedback, and equity.',
  data = $permjson${"slug": "performance-management", "title": "Performance Management", "description": "A rigorous undergraduate HR course on designing, administering, and improving performance systems. Students learn how goals, competencies, feedback, coaching, appraisal, documentation, calibration, analytics, and legal safeguards work together to improve performance and employee development. This course provides a comprehensive foundation in designing, administering, and improving performance systems, with an emphasis on modern practices including coaching, continuous feedback, and equity.", "topics": [{"id": "c0f7c852-53dc-4b5f-aebb-306ce267cffa", "type": "topic", "title": "Performance Strategy and Organizational Alignment", "description": "Students learn why performance management exists: to connect individual work, team priorities, culture, development, and organizational results without reducing people to rating forms.", "children": [{"id": "ab975684-e2f5-42ff-96ee-61bed900a93b", "type": "subtopic", "title": "Strategic purpose of performance management", "children": [{"id": "fac7ffa8-9198-4538-90b9-7d9548738ff5", "type": "concept", "title": "alignment"}, {"id": "2db08913-ca3b-44ef-90fa-784a7657ab73", "type": "concept", "title": "accountability"}, {"id": "38ad0211-0396-4ca9-bfc6-b48cac5f09f6", "type": "concept", "title": "development"}, {"id": "935295aa-ac52-4752-83ba-2c661b9d92c1", "type": "concept", "title": "recognition"}, {"id": "72491579-da25-4760-a3aa-b68f8b97ee65", "type": "concept", "title": "workforce decisions"}], "description": "This subtopic clarifies the business and human goals of performance management so students can judge whether a system is useful or merely bureaucratic."}, {"id": "a32a3df6-7563-4cfd-9da4-a9a708d3d4c5", "type": "subtopic", "title": "Performance management cycle", "children": [{"id": "ca3ce1f5-9f0f-40b8-81e5-2003d2bf47b8", "type": "concept", "title": "planning"}, {"id": "f45cb3cf-888e-41db-ab96-5022dde6884b", "type": "concept", "title": "monitoring"}, {"id": "d9a71bbc-03f8-4496-9372-665d367d8d06", "type": "concept", "title": "coaching"}, {"id": "1da2214a-37b4-47aa-bc18-8cea1a7c8304", "type": "concept", "title": "review"}, {"id": "227f76f0-6e27-47ee-b00a-435c49b0852d", "type": "concept", "title": "reward and development actions"}], "description": "Students learn the recurring rhythm that turns strategy into expectations, check-ins, evidence, feedback, development, and decisions."}, {"id": "3b0be191-6f1c-4a9d-b508-6035704e7b9a", "type": "subtopic", "title": "Stakeholders and system tensions", "children": [{"id": "edc55d71-a2af-4730-a5fd-fd13b3bccbc0", "type": "concept", "title": "employee trust"}, {"id": "f7ba1004-3606-4c07-bdfd-33e4615a47e9", "type": "concept", "title": "manager workload"}, {"id": "368c1670-dbbd-4a20-a24e-9af5bd97ba25", "type": "concept", "title": "HR governance"}, {"id": "e69a5714-3ee4-40e1-93a2-e98681f8536a", "type": "concept", "title": "legal defensibility"}, {"id": "c1e7f037-38df-4da5-a4d3-be05bf5c1efd", "type": "concept", "title": "business outcomes"}], "description": "The course surfaces the real tradeoffs among employees, managers, HR, legal, executives, and customers."}]}, {"id": "e80c1862-c35c-4965-8298-28d4ac9505a8", "type": "topic", "title": "Goal Setting, OKRs, and Performance Expectations", "description": "This section teaches students how clear goals and expectations make performance conversations more fair, specific, and useful.", "children": [{"id": "fb27cf68-5840-4d94-82d2-00ef4971ac66", "type": "subtopic", "title": "Goal-setting theory", "children": [{"id": "f7153a4d-96e2-438b-b0ce-410a71a92339", "type": "concept", "title": "specificity"}, {"id": "f40a737a-ec89-4622-ae34-df804a73fe25", "type": "concept", "title": "difficulty"}, {"id": "501a532a-cf2a-4476-a0e8-0f966db7d843", "type": "concept", "title": "commitment"}, {"id": "ccceef82-03a2-4838-b302-580ec7ab42b6", "type": "concept", "title": "feedback loops"}, {"id": "83f44f87-893a-4672-bdcd-be32161332b9", "type": "concept", "title": "goal conflict"}], "description": "Students learn why specific, challenging, accepted goals can improve performance when employees have ability, resources, and feedback."}, {"id": "b700ea5d-0b3b-44c2-a716-71e4ce8d17b3", "type": "subtopic", "title": "SMART goals and OKRs", "children": [{"id": "dfc332d1-0b20-443e-87ce-4c027dd01e51", "type": "concept", "title": "SMART criteria"}, {"id": "72236628-9dcc-4ab2-a469-7ac87b8d266a", "type": "concept", "title": "objectives and key results"}, {"id": "24151628-f6c2-404d-bf49-b68af1b45ad5", "type": "concept", "title": "leading indicators"}, {"id": "d2de1ba2-27f7-48f7-9f69-a047a351a32c", "type": "concept", "title": "lagging outcomes"}, {"id": "03c4eab7-cedf-44d9-acf2-e5bf156a0d3b", "type": "concept", "title": "cascading goals"}], "description": "The class compares familiar goal formats and shows when each is useful."}, {"id": "69f0fd2f-e35e-447b-b7f4-adcf718b053a", "type": "subtopic", "title": "Expectation setting for roles and teams", "children": [{"id": "b0f75453-54c5-431a-a27e-4e5a593ff3f4", "type": "concept", "title": "role clarity"}, {"id": "0a4c84de-9977-4e22-a369-bf7036d3d713", "type": "concept", "title": "service standards"}, {"id": "34055029-e2c1-4578-8be7-290deca6c15e", "type": "concept", "title": "team norms"}, {"id": "8426ca19-e01f-4207-bcc2-a82e982c7429", "type": "concept", "title": "project milestones"}, {"id": "3578ceed-d262-4957-a2fe-87040f1a9a70", "type": "concept", "title": "remote-work expectations"}], "description": "Students practice translating job responsibilities into observable standards for both individual and collaborative work."}]}, {"id": "a6ff66b0-9e3a-493d-a05b-0a54a9432c07", "type": "topic", "title": "Competency Frameworks and Behavioral Standards", "description": "Students learn how organizations describe the behaviors, skills, and values needed for success across roles and levels.", "children": [{"id": "15ea9592-3486-4749-9360-9d6f32a40fbc", "type": "subtopic", "title": "Competency model design", "children": [{"id": "60f504c6-53b6-487b-811e-18c40afd2505", "type": "concept", "title": "technical competencies"}, {"id": "db38b69a-a963-42ef-a714-2d97dfa6ad24", "type": "concept", "title": "leadership competencies"}, {"id": "5fc7f2e7-0272-49b1-8ded-7a29728a84ae", "type": "concept", "title": "behavioral indicators"}, {"id": "2b51e2a0-b5ea-4081-96ee-b1a621880248", "type": "concept", "title": "leveling"}, {"id": "8da6269f-940c-409b-9bed-f71c80affcc0", "type": "concept", "title": "validation"}], "description": "This subtopic explains how competencies are selected, defined, validated, and kept practical."}, {"id": "9f03715a-5aeb-46a8-bf45-3f4fa64782f4", "type": "subtopic", "title": "Values and culture in performance", "children": [{"id": "6837123a-4c8a-4e39-8437-6eb966f64f5f", "type": "concept", "title": "organizational values"}, {"id": "a9ce15ce-5f77-42cd-a019-4963568d6458", "type": "concept", "title": "citizenship behavior"}, {"id": "34ae6f35-8131-42da-9e7e-598dbb952a2f", "type": "concept", "title": "collaboration"}, {"id": "5db011e9-db0a-42ab-8892-2e61cdb38aca", "type": "concept", "title": "inclusion"}, {"id": "98267a95-ad58-45e3-83f7-15a7b3023cf5", "type": "concept", "title": "ethical conduct"}], "description": "Students examine how culture becomes visible through behavior and how vague values can become unfair if not translated into examples."}, {"id": "79f3a846-f1ca-40cc-a94e-c6ff03b250b6", "type": "subtopic", "title": "Career and development links", "children": [{"id": "8bec6ab9-045c-410d-a3c7-55870f752862", "type": "concept", "title": "career paths"}, {"id": "5e5d132f-6af2-4ea9-9717-9dd5acd1b92e", "type": "concept", "title": "skill gaps"}, {"id": "e8b1765f-fc89-4c5a-b1fe-2f023deacbac", "type": "concept", "title": "development goals"}, {"id": "374fa0fa-a55c-45f7-ba4e-c37a6779fc59", "type": "concept", "title": "promotion readiness"}, {"id": "c46e98f0-7737-4118-9535-a3a6ffee38f4", "type": "concept", "title": "succession planning"}], "description": "The course connects competency frameworks to growth, mobility, succession, and learning plans."}]}, {"id": "d757d1bb-58bf-4652-ae0a-d5208ca80089", "type": "topic", "title": "Performance Measures, Evidence, and Documentation", "description": "This unit helps students distinguish evidence-based performance assessment from impressions, anecdotes, and recency bias.", "children": [{"id": "f92d1ad6-0f91-49ce-b994-771e00fb2e17", "type": "subtopic", "title": "Measure design", "children": [{"id": "ab3a6037-ea31-4bcd-9554-3e44b76913d9", "type": "concept", "title": "quality"}, {"id": "51a9f42f-13ac-4fa8-bfcf-bb6f023dd1b8", "type": "concept", "title": "quantity"}, {"id": "e5134d11-ae04-4003-9cbb-6b1ba0faf51f", "type": "concept", "title": "timeliness"}, {"id": "574f9330-628a-45ef-bb0d-566248cde9ee", "type": "concept", "title": "customer impact"}, {"id": "d7fe452c-fc13-41e4-a477-b548e27c20fa", "type": "concept", "title": "behavioral measures"}], "description": "Students learn to choose performance measures that are relevant, controllable, balanced, and resistant to gaming."}, {"id": "b257c67a-c545-4ba0-b3c2-a6fdf79cc340", "type": "subtopic", "title": "Evidence collection", "children": [{"id": "abe24f2d-d46d-4bac-8147-8356dc9c4ca7", "type": "concept", "title": "work samples"}, {"id": "486242b1-3e54-4779-b9d5-59f57b183a36", "type": "concept", "title": "metric dashboards"}, {"id": "892636ca-b230-47ce-a235-1d81338f4263", "type": "concept", "title": "stakeholder input"}, {"id": "91967616-cf5f-46e6-84a2-e5dc25f3e75c", "type": "concept", "title": "self-assessments"}, {"id": "33d749c1-2415-435b-a9a5-b47a7fb1ecd8", "type": "concept", "title": "manager notes"}], "description": "The course teaches students how managers gather fair evidence throughout the year."}, {"id": "23189ceb-5a40-4db3-b692-d940cac64cfd", "type": "subtopic", "title": "Documentation quality", "children": [{"id": "118b8a22-075f-40a5-854f-d5af7aa85e8d", "type": "concept", "title": "specific examples"}, {"id": "d38cf760-e478-4a3d-9d11-bc14b668a5f7", "type": "concept", "title": "dates and impact"}, {"id": "421c7d56-f8e8-4dc1-b150-8d468b029fd1", "type": "concept", "title": "objective language"}, {"id": "af797b94-069e-4e31-9ae0-a871bb121354", "type": "concept", "title": "pattern tracking"}, {"id": "c2a5527b-1883-4d4a-9b44-9680e5f70914", "type": "concept", "title": "record retention"}], "description": "Students learn how factual documentation supports feedback, development, accountability, and legal defensibility."}]}, {"id": "9573e296-1e3f-4c1a-a6a4-970421e88d8a", "type": "topic", "title": "Appraisal Methods and Rating Design", "description": "Students compare major appraisal methods and learn how design choices shape accuracy, fairness, administrative burden, and employee trust.", "children": [{"id": "7d264309-0259-42f6-9d13-af9c3b3d154f", "type": "subtopic", "title": "Traditional appraisal methods", "children": [{"id": "b6e1ec35-87aa-4832-9271-d7f33bd289d6", "type": "concept", "title": "graphic rating scales"}, {"id": "0e81a90a-36eb-4778-95ff-f9690f53da69", "type": "concept", "title": "behaviorally anchored rating scales"}, {"id": "2c40ebfb-25a7-44c3-b68f-0d50446ece82", "type": "concept", "title": "essay reviews"}, {"id": "f981b549-6043-4c28-90aa-b67d4d27727d", "type": "concept", "title": "critical incidents"}, {"id": "4d203984-31f1-413b-ba93-9772aa8eb981", "type": "concept", "title": "forced distribution"}], "description": "Students evaluate common rating and review approaches used in organizations."}, {"id": "bf9d07cb-7e39-4837-8f3e-0f6fd73f8816", "type": "subtopic", "title": "Multi-source feedback", "children": [{"id": "5840b447-42dd-49a5-be4e-7c7fdef65c43", "type": "concept", "title": "peer feedback"}, {"id": "85c73a0a-7b10-415c-9e7d-cbc500691c20", "type": "concept", "title": "direct reports"}, {"id": "037de4e0-da0e-45e0-9ea4-537c42b518d8", "type": "concept", "title": "customer input"}, {"id": "ba31c1cf-bfff-4e46-be9e-95f475699482", "type": "concept", "title": "confidentiality"}, {"id": "7d15ef58-18d8-4d5a-b07a-2134c9d94acb", "type": "concept", "title": "development-only use"}], "description": "The class examines when 360-degree or stakeholder feedback helps and when it creates noise or politics."}, {"id": "70ad30f1-27dd-49f2-886a-9fdb23cb45ff", "type": "subtopic", "title": "Rating scale design", "children": [{"id": "f993a20c-6c5d-4abc-b1b9-2ad28bf0a962", "type": "concept", "title": "scale points"}, {"id": "f10291dc-c2db-4cbc-921a-11e999ad05a1", "type": "concept", "title": "behavior anchors"}, {"id": "e9ab9abe-271b-4700-a303-c2da057be847", "type": "concept", "title": "meets expectations"}, {"id": "7c2cb74e-f76d-46a8-82f9-6308a6772986", "type": "concept", "title": "rating inflation"}, {"id": "70d4c7e0-2f43-4a51-9e38-5ab27f40ac89", "type": "concept", "title": "rating compression"}], "description": "Students learn how labels, anchors, and rating definitions affect manager decisions."}]}, {"id": "2df2e91d-90cc-4f94-8b87-f1cf4cb0d547", "type": "topic", "title": "Feedback Conversations and Coaching Skills", "description": "This section gives future HR professionals and managers practical skill in conversations that improve performance while preserving dignity and trust.", "children": [{"id": "3d970b95-7ce9-4add-bfdd-5d2744c81659", "type": "subtopic", "title": "Feedback fundamentals", "children": [{"id": "07883a90-b4af-4f32-be2e-89af12679403", "type": "concept", "title": "situation-behavior-impact"}, {"id": "b65d8ee8-530e-4a2c-b71f-a13696f4dc37", "type": "concept", "title": "feedforward"}, {"id": "57dffbfa-1f51-4cdd-a1db-29c6eff5c365", "type": "concept", "title": "reinforcing feedback"}, {"id": "e88e938d-9b76-4f76-9fda-8ac948635bf3", "type": "concept", "title": "corrective feedback"}, {"id": "95f803fe-4eb7-4c86-8e54-f1edc51634a5", "type": "concept", "title": "psychological safety"}], "description": "Students learn to make feedback timely, specific, balanced, behavior-focused, and connected to impact."}, {"id": "22a95b9a-e525-44bc-9218-40a3e4ff4411", "type": "subtopic", "title": "Coaching conversations", "children": [{"id": "e0bac84a-e610-4fa0-a155-7c1230064813", "type": "concept", "title": "active listening"}, {"id": "ad7fd9b7-28bd-4993-bff4-8f6436ab8453", "type": "concept", "title": "powerful questions"}, {"id": "9b5ce28a-7fa6-4574-8c13-e2eb85da331e", "type": "concept", "title": "coaching plans"}, {"id": "ed815240-1298-4e46-8653-e912933fa5c2", "type": "concept", "title": "accountability check-ins"}, {"id": "fa9483d8-069d-452f-8966-342e07704d1b", "type": "concept", "title": "manager empathy"}], "description": "The course emphasizes questions, listening, commitment, and follow-up rather than one-way advice."}, {"id": "3f1f3eb1-52ec-47cf-8d8c-45429eb55f63", "type": "subtopic", "title": "Receiving feedback", "children": [{"id": "e002bf86-c894-4a45-9930-916c1b8f5d33", "type": "concept", "title": "defensiveness"}, {"id": "130685e3-5581-4d05-8a67-8d8d86688d49", "type": "concept", "title": "clarifying questions"}, {"id": "694f8e33-0caf-4c6e-a766-c61a5feb66c5", "type": "concept", "title": "growth mindset"}, {"id": "d41bcfec-c94f-434a-b21f-ea17d51eb648", "type": "concept", "title": "feedback triggers"}, {"id": "39681ff1-99e9-4f7f-85f6-e51822bb373e", "type": "concept", "title": "action planning"}], "description": "Students learn why performance systems also require employees to interpret, ask about, and act on feedback."}]}, {"id": "d8da56a2-95dd-4e8b-a34e-8c789b426768", "type": "topic", "title": "Calibration, Bias, and Equity", "description": "Students learn how performance systems can amplify bias and how structured calibration can improve consistency when done carefully.", "children": [{"id": "e55e6ede-a5ea-4350-909c-3fe8b19c093d", "type": "subtopic", "title": "Common rating biases", "children": [{"id": "c76d42b6-99b5-4af2-8e46-b5ee9913828b", "type": "concept", "title": "recency bias"}, {"id": "2fc3f53a-83d0-481f-ad27-3cf04943319e", "type": "concept", "title": "halo and horns"}, {"id": "fa1204d5-56c1-4566-be60-52350b751925", "type": "concept", "title": "similarity bias"}, {"id": "38a59b72-8be7-4920-b917-6427124379f1", "type": "concept", "title": "leniency and severity"}, {"id": "62d971e6-12be-4c11-900f-d497e9448902", "type": "concept", "title": "central tendency"}], "description": "This subtopic gives students a vocabulary for recognizing judgment errors in appraisal."}, {"id": "1dabfd99-3d5b-4123-bc20-9b8ac4dfad89", "type": "subtopic", "title": "Calibration processes", "children": [{"id": "e2094149-bd69-48cb-a783-896e6875f1de", "type": "concept", "title": "calibration meetings"}, {"id": "2cdbc3b2-58fa-405b-b63b-cc102bf997c3", "type": "concept", "title": "evidence review"}, {"id": "8cfe0e7d-80ae-4f4c-84b0-d96ecc2d98ae", "type": "concept", "title": "rating distributions"}, {"id": "893899a1-214d-4ceb-8054-8121e8c9a204", "type": "concept", "title": "manager challenge"}, {"id": "016cdd31-07cb-4010-8f8e-d442fa9d43e4", "type": "concept", "title": "decision logs"}], "description": "Students learn how organizations compare ratings and evidence across teams to reduce inconsistency."}, {"id": "b4e01a1d-4a10-4bf0-9835-1889996137cf", "type": "subtopic", "title": "Equity audits", "children": [{"id": "f89b39a2-ca50-4e68-81c9-91a7fe191eb9", "type": "concept", "title": "group differences"}, {"id": "6c780f73-8fb3-4002-8c14-287841266cf6", "type": "concept", "title": "promotion outcomes"}, {"id": "1de92eff-f5ff-48eb-989e-0ba4c4315ed0", "type": "concept", "title": "pay-for-performance links"}, {"id": "bdf11989-8948-4aa6-8c4e-d7111f7fef8e", "type": "concept", "title": "intersectionality"}, {"id": "dffbf825-ca80-4ad4-b42d-f390f5f1df25", "type": "concept", "title": "remediation"}], "description": "The course connects performance ratings to promotion, pay, discipline, and disparate-impact concerns."}]}, {"id": "864b8289-5cb8-4322-9bef-4a0f338d4f32", "type": "topic", "title": "Development Planning and Talent Growth", "description": "This unit reframes performance management as a developmen